import 'package:flutter/material.dart' hide BoxDecoration, BoxShadow;
import 'package:flutter_inset_shadow/flutter_inset_shadow.dart';

Widget build(BuildContext context) {
  return Container(
    decoration: BoxDecoration(
      boxShadow: [
        BoxShadow(
          offset: Offset(1, 2),
          blurRadius: 5,
          spreadRadius: 2,
          color: Colors.green,
          inset: true,
        ),
      ],
    ),
  );
}
